// Test that the mock backend seeded batches correctly
const base = window.location.origin + "/api/v1";

// Login as admin first
const loginRes = await fetch(`${base}/auth/login`, {
  method: "POST",
  headers: { "Content-Type": "application/json" },
  body: JSON.stringify({ username: "admin", password: "admin123" })
});
const loginBody = await loginRes.json();
console.log("Login:", loginBody.token ? "Success" : "Failed", loginBody);

if (loginBody.token) {
  // Fetch batches
  const batchRes = await fetch(`${base}/admin/student-batches`, {
    headers: { "Authorization": `Bearer ${loginBody.token}` }
  });
  const batches = await batchRes.json();
  console.log("Batches:", batches);

  // Fetch a batch detail
  if (batches.length > 0) {
    const detailRes = await fetch(`${base}/admin/student-batches/${batches[0].id}`, {
      headers: { "Authorization": `Bearer ${loginBody.token}` }
    });
    const detail = await detailRes.json();
    console.log("Batch detail students count:", detail.students?.length);
  }
}

